import fs from 'node:fs/promises';
import iconv from 'iconv-lite';
import { scanSource } from '../language-syntax.ts';
import type { FileEntry } from '../types.ts';
import type { ThirdPartyAnalysisDiagnostic, ThirdPartyEvidence } from './types.ts';

const HEADER_BYTES = 32 * 1024;

export interface HeaderEvidenceResult {
  evidence: ThirdPartyEvidence[];
  diagnostics: ThirdPartyAnalysisDiagnostic[];
  generated: boolean;
}

async function readHeader(entry: FileEntry, signal?: AbortSignal): Promise<string> {
  signal?.throwIfAborted();
  const handle = await fs.open(entry.path, 'r');
  try {
    signal?.throwIfAborted();
    const size = Math.min(HEADER_BYTES, Math.max(0, entry.sizeBytes));
    const buffer = Buffer.alloc(size);
    const { bytesRead } = await handle.read(buffer, 0, size, 0);
    signal?.throwIfAborted();
    const encoding = iconv.encodingExists(entry.encoding) ? entry.encoding : 'utf8';
    return iconv.decode(buffer.subarray(0, bytesRead), encoding).replace(/^\uFEFF/, '');
  } finally {
    await handle.close();
  }
}

export async function inspectSourceHeader(entry: FileEntry, signal?: AbortSignal): Promise<HeaderEvidenceResult> {
  let text: string;
  try {
    text = await readHeader(entry, signal);
  } catch (error) {
    if (signal?.aborted) throw error;
    return {
      evidence: [], generated: false,
      diagnostics: [{
        code: 'evidence-read-failed', file: entry.relPath,
        message: '无法读取文件头部，第三方风险证据可能不完整。',
        suggestion: '请检查文件权限后重新扫描。',
      }],
    };
  }
  signal?.throwIfAborted();
  const comments = scanSource(text, entry.ext).flatMap((line, index) =>
    line.comments.map((comment) => ({ comment, line: index + 1 })));
  const evidence: ThirdPartyEvidence[] = [];
  let generated = false;
  for (const { comment, line } of comments) {
    const spdx = /\bSPDX-License-Identifier\s*:\s*([A-Za-z0-9.+-]+)/i.exec(comment);
    if (spdx) {
      evidence.push({
        ruleId: 'source-header-spdx', source: 'source-header',
        location: { file: entry.relPath, line },
        detail: '源码注释包含 SPDX 许可证标识。', licenseId: spdx[1],
      });
    } else if (/\b(?:licensed under|permission is hereby granted|gnu (?:general|lesser) public license|apache license|mit license)\b/i.test(comment)) {
      evidence.push({
        ruleId: 'source-header-license-text', source: 'source-header',
        location: { file: entry.relPath, line },
        detail: '源码注释包含许可证声明，需核验授权与归属。',
      });
    }
    if (/\b(?:code generated .* do not edit|auto-generated|autogenerated)\b/i.test(comment)) {
      generated = true;
      evidence.push({
        ruleId: 'generated-comment-marker', source: 'generated-marker',
        location: { file: entry.relPath, line },
        detail: '源码注释包含明确的自动生成标记。',
      });
    } else if (/\b(?:generated by|@generated)\b/i.test(comment)) {
      generated = true;
      evidence.push({
        ruleId: 'generated-comment-hint', source: 'generated-marker',
        location: { file: entry.relPath, line },
        detail: '源码注释包含生成工具提示。',
      });
    }
  }
  return { evidence, diagnostics: [], generated };
}
